function openDistribution(income){const c=cycleBounds(income.occurred_on);distributionContext={income,cycle:c};$('distributionInfo').textContent=`Ingreso ${money(income.amount)} del ${income.occurred_on}. Define cuánto quieres reservar en cada apartado para el ciclo ${c.start} al ${c.end}.`;$('distributionRows').innerHTML=ownerEnvelopes().map(e=>`<label class="distribution-row"><span>${safe(e.name)}${Number(e.auto_percent)>0?` · ${Number(e.auto_percent)}% automático`:''}</span><input class="dist-amount" data-id="${e.id}" type="number" min="0" step="0.01" value="${envelopeAvailableForCycle(e,c).toFixed(2)}"></label>`).join('')||'<div class="empty">No hay apartados para distribuir.</div>';$('distributionCard').classList.remove('hidden');window.scrollTo({top:0,behavior:'smooth'})}
async function saveDistribution(){if(!distributionContext)return;const {income,cycle}=distributionContext,rows=[...document.querySelectorAll('.dist-amount')];for(const input of rows){const e=envelopes.find(x=>x.id===input.dataset.id),amount=Math.max(0,Number(input.value)||0);const payload={owner_id:currentOwnerId,envelope_id:e.id,cycle_start:cycle.start,cycle_end:cycle.end,reserved_amount:amount,created_by:me.id,note:`Distribución del ingreso ${income.id}`};const {error}=await sb.from('envelope_cycle_budgets').upsert(payload,{onConflict:'envelope_id,cycle_start'});if(error)return apiError(error)}distributionContext=null;$('distributionCard').classList.add('hidden');await refreshData(false);setView('dashboard');toast('Distribución guardada')}
