function renderShares(){const others=profiles.filter(u=>u.active&&u.id!==me.id);$('shareUser').innerHTML=others.map(u=>`<option value="${u.id}">${safe(u.full_name)} (${safe(u.username)})</option>`).join('');$('shareForm').querySelector('button').disabled=!can('share_finances')||currentOwnerId!==me.id;const mine=shares.filter(s=>s.owner_id===me.id);$('shareList').innerHTML=mine.length?mine.map(s=>{const u=profile(s.user_id);return `<div class="item"><div class="row between"><div><div class="item-title">${safe(u?.full_name||'Usuario')}</div><div class="small muted">${safe(u?.username||'')}</div></div><span class="pill ${s.permission==='write'?'blue':''}">${s.permission==='write'?'Lectura y escritura':'Solo lectura'}</span></div><button class="btn danger revoke-share" data-id="${s.id}" style="margin-top:9px">Quitar acceso</button></div>`}).join(''):'<div class="empty">No has compartido tus finanzas.</div>';document.querySelectorAll('.revoke-share').forEach(b=>b.onclick=async()=>{const {error}=await sb.from('shares').delete().eq('id',b.dataset.id);if(error)return apiError(error);await refreshData(false);setView('compartir')})}
