async function refreshUsersDirectory(show=false){await loadAll();refreshOwnerSelector();renderUsers();if(show)toast('Usuarios actualizados')}
function renderUsers(){if(me.role!=='admin')return;$('userList').innerHTML=profiles.map(u=>{const visible=tempPasswords[u.id];return `<div class="item"><div class="row between"><div><div class="item-title">${safe(u.full_name)}</div><div class="small muted">${u.role==='admin'?'Administrador':'Usuario'} · ${safe(u.username)}</div></div><span class="pill ${u.active?'good':'bad'}">${u.active?'Activo':'Inactivo'}</span></div><div class="credential-box"><div class="credential-line"><span>Usuario</span><code>${safe(u.username)}</code></div><div class="credential-line"><span>Contraseña</span>${visible?`<code>${safe(visible)}</code>`:'<span class="protected">Protegida por Supabase</span>'}</div></div><div class="row" style="margin-top:9px">${u.active?`<button class="btn primary view-user-finances" data-id="${u.id}">Ver / administrar finanzas</button>`:''}${u.id!==me.id?`<button class="btn secondary toggle-user" data-id="${u.id}">${u.active?'Desactivar':'Activar'}</button><button class="btn ghost perms-user" data-id="${u.id}">Permisos</button><button class="btn ghost reset-pass" data-id="${u.id}">Nueva contraseña</button>`:'<span class="small muted">Tu contraseña se cambia en Ajustes.</span>'}</div></div>`}).join('');document.querySelectorAll('.view-user-finances').forEach(b=>b.onclick=()=>{currentOwnerId=b.dataset.id;refreshOwnerSelector();setView('dashboard');toast('Administrando finanzas de '+(profile(b.dataset.id)?.full_name||'usuario'))});document.querySelectorAll('.toggle-user').forEach(b=>b.onclick=async()=>{const u=profile(b.dataset.id);const {error}=await sb.from('profiles').update({active:!u.active}).eq('id',u.id);if(error)return apiError(error);await refreshUsersDirectory()});document.querySelectorAll('.perms-user').forEach(b=>b.onclick=()=>editPermissions(b.dataset.id));document.querySelectorAll('.reset-pass').forEach(b=>b.onclick=()=>resetPassword(b.dataset.id))}
async function editPermissions(id){const u=profile(id),p=permissions.find(x=>x.user_id===id)||{};if(!u)return;const current=PERMS.map(([k,l])=>`${l}: ${p[k]?'Sí':'No'}`).join('\n');const choice=prompt(`Permisos actuales de ${u.full_name}:\n\n${current}\n\nEscribe TODO para habilitar todos o NINGUNO para deshabilitar todos.`);if(choice===null)return;const v=choice.trim().toUpperCase();if(!['TODO','NINGUNO'].includes(v))return toast('Sin cambios');const update=Object.fromEntries(PERMS.map(([k])=>[k,v==='TODO']));const {error}=await sb.from('user_permissions').update(update).eq('user_id',id);if(error)return apiError(error);await refreshUsersDirectory();toast('Permisos actualizados')}
function makeTempPassword(){const b=new Uint32Array(2);crypto.getRandomValues(b);return `MiDinero-${b[0].toString(36)}${b[1].toString(36)}`.slice(0,20)}
async function resetPassword(id){const u=profile(id),suggested=makeTempPassword(),password=prompt(`Nueva contraseña temporal para ${u.full_name}:`,suggested);if(password===null)return;if(password.length<8)return toast('Mínimo 8 caracteres');const {data,error}=await sb.functions.invoke('reset-user-password',{body:{user_id:id,password}});if(error)return apiError(error);if(data?.error)return toast(data.error);tempPasswords[id]=password;renderUsers();toast('Contraseña temporal actualizada')}
function reportEvents(){
 const state=Object.fromEntries(own(accounts).map(a=>[a.id,Number(a.opening_balance)||0])),events=[];ownerLedger().forEach(t=>events.push({date:t.occurred_on,created:t.created_at||'',kind:'ledger',data:t}));ownerCardPayments().forEach(p=>events.push({date:p.occurred_on,created:p.created_at||'',kind:'card',data:p}));events.sort((a,b)=>(a.date+a.created).localeCompare(b.date+b.created));const rows=[];
 for(const ev of events){if(ev.kind==='ledger'){const t=ev.data,a=accounts.find(x=>x.id===t.account_id),before=state[t.account_id]??0,amt=Number(t.amount),credit=a?.account_type==='credit';let after=before;if(credit){if(t.entry_type==='expense')after+=amt;else if(t.entry_type==='income')after=Math.max(0,after-amt);else after=Math.max(0,after+amt*(Number(t.adjustment_direction)||1))}else{if(t.entry_type==='income')after+=amt;else if(t.entry_type==='expense')after-=amt;else after+=amt*(Number(t.adjustment_direction)||1)}state[t.account_id]=after;rows.push({id:t.id,date:t.occurred_on,created_at:t.created_at,updated_at:t.updated_at,type:t.entry_type==='income'?'Ingreso':t.entry_type==='expense'?'Gasto':'Ajuste',account:a?.name||'',envelope:envelopes.find(e=>e.id===t.envelope_id)?.name||'',amount:amt,before,after,creator:profile(t.created_by)?.full_name||'',comment:t.comment||'',fixed:fixedExpenses.find(f=>f.id===t.fixed_expense_id)?.name||'',business:!!t.business_related})}else{const p=ev.data,s=accounts.find(a=>a.id===p.source_account_id),cr=accounts.find(a=>a.id===p.credit_account_id),amt=Number(p.amount),bs=state[p.source_account_id]??0,bc=state[p.credit_account_id]??0,as=bs-amt,ac=Math.max(0,bc-amt);state[p.source_account_id]=as;state[p.credit_account_id]=ac;rows.push({id:p.id,date:p.occurred_on,created_at:p.created_at,updated_at:p.updated_at,type:'Pago tarjeta',account:`${s?.name||''} → ${cr?.name||''}`,envelope:'',amount:amt,before:`${money(bs)} / deuda ${money(bc)}`,after:`${money(as)} / deuda ${money(ac)}`,creator:profile(p.created_by)?.full_name||'',comment:p.comment||'',fixed:'',business:false})}}
 return rows;
}
function fillReportCycles(){const old=$('reportCyclePreset').value,opts=[];let c=cycleBounds();for(let i=0;i<12;i++){opts.push(c);c=previousCycle(c)}$('reportCyclePreset').innerHTML=opts.map((x,i)=>`<option value="${x.start}|${x.end}">${i===0?'Ciclo actual':'Ciclo anterior '+i}: ${x.start} → ${x.end}</option>`).join('')+'<option value="custom">Personalizado</option>';if(old&&[...$('reportCyclePreset').options].some(o=>o.value===old))$('reportCyclePreset').value=old;else $('reportCyclePreset').selectedIndex=0}
function renderReport(){
 fillReportCycles();if(!$('reportFrom').value||!$('reportTo').value){const c=cycleBounds();$('reportFrom').value=c.start;$('reportTo').value=c.end}const from=$('reportFrom').value,to=$('reportTo').value,rows=reportEvents().filter(r=>(!from||r.date>=from)&&(!to||r.date<=to));$('reportOwnerName').textContent=owner()?.full_name||'';$('reportPeriodText').textContent=`${from||'Inicio'} → ${to||'Hoy'}`;const income=rows.filter(r=>r.type==='Ingreso').reduce((s,r)=>s+r.amount,0),expense=rows.filter(r=>r.type==='Gasto').reduce((s,r)=>s+r.amount,0),pays=rows.filter(r=>r.type==='Pago tarjeta').reduce((s,r)=>s+r.amount,0),biz=rows.filter(r=>r.business).reduce((s,r)=>s+(r.type==='Ingreso'?r.amount:r.type==='Gasto'?-r.amount:0),0),c=cycleBounds(to||today());$('reportIncome').textContent=money(income);$('reportExpense').textContent=money(expense);$('reportReserved').textContent=money(totalReserved(c)+goalReserved());$('reportCardPayments').textContent=money(pays);$('reportDebt').textContent=money(totalDebt());$('reportBusinessCard').classList.toggle('hidden',!ownerFinanceSetting().business_mode);$('reportBusiness').textContent=money(biz);$('printBtn').disabled=!can('generate_pdf');$('exportCsvBtn').disabled=!can('generate_pdf');$('reportBody').innerHTML=rows.length?rows.map(r=>`<tr><td>${safe(r.date)}</td><td><span class="nowrap">${safe((r.created_at||'').replace('T',' ').slice(0,16))}</span>${r.updated_at&&r.updated_at!==r.created_at?`<br><span class="small muted">Mod. ${safe(r.updated_at.replace('T',' ').slice(0,16))}</span>`:''}</td><td>${safe(r.type)}</td><td>${safe(r.account)}</td><td>${safe(r.envelope)}</td><td>${money(r.amount)}</td><td>${typeof r.before==='number'?money(r.before):safe(r.before)}</td><td>${typeof r.after==='number'?money(r.after):safe(r.after)}</td><td>${safe(r.creator)}</td><td>${safe(r.comment)}${r.fixed?` · Pago fijo: ${safe(r.fixed)}`:''}${r.business?' · Negocio':''}</td></tr>`).join(''):'<tr><td colspan="10">Sin movimientos.</td></tr>';renderAudit();
}
function renderAudit(){const show=me.role==='admin';$('auditCard').classList.toggle('hidden',!show);if(!show)return;const rows=auditLogs.filter(x=>x.owner_id===currentOwnerId).slice(0,30);$('auditList').innerHTML=rows.length?rows.map(x=>{const actor=profile(x.actor_id);return `<div class="audit-line"><b>${safe(actor?.full_name||'Sistema')}</b> · ${safe(x.action)} ${safe(x.entity_type)} · ${new Date(x.created_at).toLocaleString('es-MX')}</div>`}).join(''):'<div class="empty">No hay cambios registrados.</div>'}
